const PRECO = 5;
let moedas = 0;
let picaretas = 0;

const mensagem = document.querySelector("#mensagem");

function mostrar() {
  document.querySelector("#moedas").textContent = moedas;
  document.querySelector("#picaretas").textContent = picaretas;
}

document.querySelector("#minerar").addEventListener("click", () => {
  moedas += 1 + picaretas;
  mostrar();
});

document.querySelector("#comprar").addEventListener("click", () => {
  if (moedas >= PRECO) {
    moedas -= PRECO;
    picaretas++;
    mensagem.textContent = "Você comprou uma picareta!";
  } else {
    mensagem.textContent = `Moedas insuficientes: ${moedas} de ${PRECO}.`;
  }
  mostrar();
});

