const cartas = [
  { nome: "Herói", imagem: "midia/heroi.svg" },
  { nome: "Espada", imagem: "midia/espada.svg" },
  { nome: "Castelo", imagem: "midia/castelo.svg" },
  { nome: "Planeta", imagem: "midia/planeta.svg" },
];

const mao = document.querySelector("#mao");
const contagem = document.querySelector("#contagem");

function atualizarContagem() {
  const total = mao.querySelectorAll(".carta").length;
  if (total === 0) {
    contagem.textContent = "Sua mão está vazia.";
  } else if (total === 1) {
    contagem.textContent = "1 carta na mão";
  } else {
    contagem.textContent = `${total} cartas na mão`;
  }
}

for (const carta of cartas) {
  const item = document.createElement("li");
  item.classList.add("carta");

  const imagem = document.createElement("img");
  imagem.src = carta.imagem;
  imagem.alt = carta.nome;

  const nome = document.createElement("p");
  nome.textContent = carta.nome;

  const botao = document.createElement("button");
  botao.classList.add("descartar");
  botao.textContent = "Descartar";
  botao.addEventListener("click", () => {
    item.remove();
    atualizarContagem();
  });

  item.append(imagem, nome, botao);
  mao.append(item);
}

atualizarContagem();

