solucao.script.js:
const form = document.querySelector("#nova");
const campo = document.querySelector("#tarefa");
const lista = document.querySelector("#lista");
const pendentes = document.querySelector("#pendentes");

function atualizarPendentes() {
  const total = lista.querySelectorAll("li:not(.feita)").length;
  if (total === 0) {
    pendentes.textContent = "Nenhuma tarefa pendente";
  } else if (total === 1) {
    pendentes.textContent = "1 tarefa pendente";
  } else {
    pendentes.textContent = `${total} tarefas pendentes`;
  }
}

function criarTarefa(texto) {
  const item = document.createElement("li");

  const descricao = document.createElement("span");
  descricao.classList.add("texto");
  descricao.textContent = texto;
  descricao.addEventListener("click", () => {
    item.classList.toggle("feita");
    atualizarPendentes();
  });

  const apagar = document.createElement("button");
  apagar.classList.add("apagar");
  apagar.textContent = "Apagar";
  apagar.addEventListener("click", () => {
    item.remove();
    atualizarPendentes();
  });

  item.append(descricao, apagar);
  lista.append(item);
}

form.addEventListener("submit", (evento) => {
  evento.preventDefault();
  const texto = campo.value.trim();
  if (texto !== "") {
    criarTarefa(texto);
    atualizarPendentes();
  }
  campo.value = "";
  campo.focus();
});

document.querySelector("#limpar").addEventListener("click", () => {
  lista.querySelectorAll("li.feita").forEach((item) => item.remove());
  atualizarPendentes();
});

atualizarPendentes();
